        ["start.title"] = ("FUNKY LAUNCHER", "FUNKY LAUNCHER"),
        ["start.brand"] = ("FUNKYPLAY  ·  ИГРЫ  ·  МОДЫ  ·  СОФТ", "FUNKYPLAY  ·  GAMES  ·  MODS  ·  SOFTWARE"),
        ["tile.mods"] = ("Сборки модов", "Mod packs"),
        ["tile.mods.text"] = ("Neon Nights, Nova Nights и Atomic Nights — Cyberpunk 2077, Starfield и Fallout 4", "Neon Nights, Nova Nights and Atomic Nights — Cyberpunk 2077, Starfield and Fallout 4"),
        ["tile.soft"] = ("Софт", "Software"),
        ["tile.soft.text"] = ("Полезные программы для игр и ПК", "Useful programs for games and PC"),
        ["tile.video"] = ("Видео и обзоры", "Videos and reviews"),
        ["tile.video.text"] = ("Гайды, обзоры модов и софта на YouTube", "Guides, mod and software reviews on YouTube"),
        ["start.text"] = ("Сборки модов от Funky: проверка совместимости, установка, запуск и починка. Моды живут в отдельной папке, в папку игры ставятся только несколько файлов-загрузчиков модов — кнопка «Вернуть чистую игру» их убирает. От тебя нужны установленная игра и аккаунт Nexus Mods (подойдёт бесплатный) — дальше лаунчер ведёт сам.", "Mod packs by Funky: compatibility check, install, launch and repair. Mods live in their own folder; only a few mod loader files go into the game folder, and \"Restore clean game\" removes them. All you need is the game installed and a Nexus Mods account (a free one works) — the launcher guides you through the rest."),
        ["start.premium"] = ("С Nexus Premium файлы скачиваются сами.", "With Nexus Premium, files download automatically."),
        ["start.free"] = ("Без Premium — бесплатно: у каждого файла нажимаешь «Slow download», лаунчер ведёт по шагам (около 1–2 часов).", "Without it, it's free: you press \"Slow download\" for each file, the launcher guides you step by step (about 1–2 hours)."),
        ["start.library"] = ("ОТКРЫТЬ БИБЛИОТЕКУ", "OPEN LIBRARY"),
        ["start.whatsnew"] = ("Что нового · версия {0}", "What's new · version {0}"),
        ["start.whatsnew.badge"] = ("НОВОЕ", "NEW"),
        ["site.tip"] = ("Наш сайт: сборки, инструкции, ответы на вопросы", "Our site: modlists, guides, FAQ"),
        ["site.name"] = ("Сайт", "Website"),
        ["site.modlist"] = ("Страница сборки на сайте", "Modlist page on the site"),
        ["start.whatsnew.items"] = ("• Отчёт об ошибке: в него теперь попадают файлы вылетов REDscope — так мы быстрее найдём причину вылета\n• Графика: переключатель «Полная графика / Облегчённая». Если у видеокарты 8 ГБ памяти или меньше, лаунчер посоветует облегчённую\n• Откат: кнопка «Вернуться к версии X» возвращает сборку на предыдущую версию\n• Игра находится сама. Если не нашлась — кнопка «Указать папку игры»\n• Вход в Nexus: окно «Вход в Nexus — 3 шага» подскажет, куда нажать, а лаунчер сам заметит, что вход выполнен\n• Перед установкой лаунчер проверяет файлы игры и предупреждает, если они отличаются от нужной версии\n• Neon Nights 0.1.6: обновлены 4 мода. Мод войн банд и CyberScript выключены по умолчанию, включить их можно в Mod Organizer", "• Error report: it now includes the REDscope crash files, so we can find the cause of a crash faster\n• Graphics: a \"Full graphics / Lightweight\" switch. If your graphics card has 8 GB of memory or less, the launcher suggests Lightweight\n• Rollback: the \"Back to version X\" button returns the modlist to the previous version\n• The launcher finds the game by itself. If it doesn't, use the \"Show the game folder\" button\n• Nexus login: the \"Nexus login — 3 steps\" window shows where to click, and the launcher notices by itself that you are logged in\n• Before installing, the launcher checks the game files and warns you if they differ from the needed version\n• Neon Nights 0.1.6: 4 mods updated. The gang wars mod and CyberScript are off by default; you can turn them on in Mod Organizer"),
        ["start.support"] = ("Поддержка", "Support"),
        ["start.support.text"] = ("Что-то не работает? Соберите отчёт и отправьте его нам в Telegram — разберёмся.", "Something not working? Make a report and send it to us on Telegram — we'll sort it out."),
        ["start.support.write"] = ("Написать в поддержку", "Contact support"),
        ["start.support.report"] = ("Собрать отчёт об ошибке", "Make an error report"),
        ["start.report.working"] = ("Собираем отчёт…", "Making the report…"),
        ["start.report.done"] = ("Отчёт сохранён на рабочий стол: {0}. Открыли чат поддержки с готовым сообщением — перетащите туда файл из открывшейся папки, допишите, что случилось, и отправьте.", "Report saved to the Desktop: {0}. The support chat is open with a ready message — drag the file from the opened folder into it, add what happened and send."),
        ["start.report.error"] = ("Не удалось собрать отчёт: {0}", "Could not make the report: {0}"),

