        ["soft.site"] = ("Сайт", "Website"),
        ["soft.install.confirm"] = ("Установить {0}?{1}\n\nПрограмма скачается с официального источника через winget. Лаунчер установщики не хранит.", "Install {0}?{1}\n\nThe program is downloaded from its official source via winget. The launcher does not store installers."),
        ["soft.consent"] = ("Установка программ одной кнопкой\n\nПрограммы скачиваются с сайтов их авторов через winget — менеджер программ Microsoft, встроенный в Windows. Это не наши программы, мы не связаны с их авторами: у каждой своя лицензия и политика конфиденциальности (страница — кнопка «Сайт» у программы).\n\nНажимая «Да», вы принимаете лицензии устанавливаемых программ и условия каталога winget. Windows спросит права администратора. Удалить программу можно в «Параметры → Приложения».\n\nПрограммы: {0}", "One-click install\n\nPrograms are downloaded from their authors' websites via winget, the Microsoft package manager built into Windows. They are not ours and we are not affiliated with their authors: each has its own license and privacy policy (see the Website button).\n\nBy pressing Yes you accept the licenses of the programs you install and the winget catalog terms. Windows will ask for admin rights. You can remove a program in Settings → Apps.\n\nPrograms: {0}"),
        ["soft.install.fail"] = ("Не получилось установить {0}: {1}\n\nМожно скачать с сайта программы — кнопка «Сайт».", "Could not install {0}: {1}\n\nYou can get it from the website — the Website button."),
        ["soft.open"] = ("Скачать с сайта", "Get from website"),
        ["soft.open.tg"] = ("Открыть в Telegram", "Open in Telegram"),

        ["setup.back"] = ("← Библиотека", "← Library"),
        ["setup.update"] = ("ОБНОВИТЬ ДО {0}", "UPDATE TO {0}"),
        ["setup.update.note"] = ("Новая версия {0} поставится в отдельную папку {1}. Текущая версия {2} останется — если новая не запустится, в библиотеке можно вернуться к старой. Уже скачанные моды повторно не качаются.", "The new version {0} goes into a separate folder {1}. The current version {2} stays — if the new one does not start, you can go back in the library. Mods you already downloaded are not downloaded again."),
        ["setup.verify.small"] = ("Проверить файлы", "Verify files"),
        ["inst.update.done"] = ("Готово! Версия {0} установлена. Прошлая версия сохранена — к ней можно вернуться в библиотеке.", "Done! Version {0} is installed. The previous version is kept — you can go back to it in the library."),

        ["lib.update"] = ("Обновить до {0}", "Update to {0}"),
        ["lib.update.available"] = ("Доступна версия {0}", "Version {0} is available"),
        ["lib.previous"] = ("Сохранена прошлая версия {0}", "Previous version {0} is kept"),
        ["lib.rollback"] = ("Вернуться к версии {0}", "Back to version {0}"),
        ["lib.rollback.title"] = ("Сменить версию", "Switch version"),
        ["lib.rollback.confirm"] = ("Переключиться на версию {0}?\n\nПапка: {1}\n\nТекущая версия {2} останется на диске — на неё можно вернуться так же.", "Switch to version {0}?\n\nFolder: {1}\n\nThe current version {2} stays on disk — you can switch back the same way."),
        ["lib.rollback.done"] = ("Готово: теперь играем на версии {0}.", "Done: now playing version {0}."),
        // 0.1.19 (draft, for the Copywriter): a modlist updated in place goes back to the kept version
        ["lib.rollback.inplace"] = ("Вернуться к версии {0}?\n\nМоды, которые поменяло обновление, и порядок модов станут как в {0}. Ничего не скачивается.\n\nВерсия {1} останется на диске — на неё можно вернуться той же кнопкой или кнопкой «Обновить».", "Go back to version {0}?\n\nThe mods the update changed and the mod order become as in {0}. Nothing is downloaded.\n\nVersion {1} stays on disk — you can go back to it with the same button or with Update."),
        ["lib.deleteold"] = ("Удалить прошлую версию", "Delete previous version"),
        ["lib.deleteold.confirm"] = ("Удалить прошлую версию {0}?\n\nПапка: {1}\n\nЭто нельзя отменить. Скачанные архивы модов не удаляются.", "Delete previous version {0}?\n\nFolder: {1}\n\nThis cannot be undone. Downloaded mod archives are kept."),
        ["lib.deleting"] = ("Удаляем прошлую версию…", "Deleting the previous version…"),
        ["lib.deleted"] = ("Прошлая версия удалена.", "Previous version deleted."),
        ["lib.delete.error"] = ("Не удалось удалить: {0}", "Could not delete: {0}"),

        // 18+ add-on (texts from Моддинг\Юридические\Схема 18+.md, 3.2–3.3)
        ["addon.line.off"] = ("Дополнение 18+ · выключено", "18+ add-on · off"),
        ["addon.line.on"] = ("Дополнение 18+ · включено", "18+ add-on · on"),
        ["addon.line.reapply"] = ("Дополнение 18+ · нужно применить снова", "18+ add-on · needs to be applied again"),
        ["addon.title"] = ("Дополнение 18+", "18+ add-on"),
        ["comp.title"] = ("СОСТАВ СБОРКИ", "MODLIST CONTENTS"),
        ["comp.lang"] = ("Язык сборки", "Modlist language"),
        ["comp.lang.ru"] = ("Русская", "Russian"),
        ["comp.lang.en"] = ("Английская", "English"),
        ["comp.lang.hint"] = ("Для русской версии поверх сборки ставятся переводы модов. Язык можно сменить потом, без переустановки. Язык самой игры — в настройках игры.", "The Russian version adds mod translations on top of the modlist. You can switch the language later without reinstalling. The game's own language is set in the game settings."),
        ["comp.lang.hint.installed"] = ("Смена языка занимает пару минут. Сборка не переустанавливается.", "Switching the language takes a couple of minutes. The modlist is not reinstalled."),
        ["comp.adult"] = ("Дополнение 18+", "18+ add-on"),
        ["comp.adult.hint"] = ("Моды для взрослых ставятся отдельно. Выключено, пока не включишь сам.", "Adult mods are installed separately. Off until you turn it on."),
        ["comp.adult.hint.on"] = ("Включено. Нажми, чтобы изменить или выключить.", "On. Click to change or turn it off."),
        ["comp.apply"] = ("Применить изменения", "Apply changes"),
        ["trans.title"] = ("Русские названия вещей", "Russian item names"),
        ["trans.note"] = ("Названия в русской версии переведены автоматически с помощью ИИ, возможны ошибки. Моды и их названия принадлежат авторам, их файлы не изменяются. Перевод названий — наш отдельный патч, он собирается на компьютере игрока.", "Russian item names are machine-translated with AI, mistakes are possible. Mods and their names belong to their authors; their files are not modified. The translation is our separate patch built on the player's PC."),
        ["trans.credit"] = ("Авторство: {0} — {1}, страница на Nexus Mods: ", "Credit: {0} — {1}, Nexus Mods page: "),
        ["trans.credit.tail"] = (" Перевод названий — наш отдельный патч, файлы авторов не меняются и не раздаются.", " The name translation is our separate patch; the authors' files are not modified or redistributed."),
        ["trans.credits.general"] = ("Все моды сборки принадлежат их авторам. Ссылка на страницу каждого мода — в списке модов сборки.", "All mods in this modlist belong to their authors. Each mod's page is linked in the modlist."),
        ["trans.rebuild"] = ("Пересобрать русские названия", "Rebuild the Russian names"),
        ["trans.building"] = ("Собираю русские названия…", "Building the Russian names…"),
        ["trans.done"] = ("Готово: русские названия собраны ({0}). Можно играть.", "Done: the Russian names are built ({0}). You can play."),
        ["trans.skipped"] = ("Русские названия нужны только для русской версии сборки.", "The Russian names are only for the Russian version of the modlist."),
        ["trans.failed"] = ("Русские названия не собрались, сборка работает, но эти названия останутся на английском. Причина записана в отчёт об ошибке. ({0})", "The Russian names could not be built. The modlist works, but those names stay in English. The reason is saved in the error report. ({0})"),
        ["trans.err.mo2"] = ("Закройте Mod Organizer 2 и нажмите «Пересобрать русские названия».", "Close Mod Organizer 2 and press \"Rebuild the Russian names\"."),
        ["comp.lang.working"] = ("Ставлю русскую версию…", "Installing the Russian version…"),
        ["comp.lang.done.ru"] = ("Готово: русская версия включена ({0} переводов). Можно играть.", "Done: Russian is on ({0} translations). You can play."),
        ["comp.lang.done.en"] = ("Готово: английская версия сборки. Переводы выключены, файлы остались — вернуть русскую можно в любой момент.", "Done: the modlist is in English. Translations are off (files kept) — switch back any time."),
        ["comp.lang.notdownloaded"] = ("Не удалось скачать {0} переводов — эти моды останутся на английском. Нажмите «Применить изменения» ещё раз позже.", "Could not download {0} translations — those mods stay in English. Try \"Apply changes\" again later."),
        ["addon.about"] = ("Контент для взрослых к сборке {0}. Выключено по умолчанию. Только для игроков старше 18 лет.", "Adult content for the {0} modlist. Off by default. For players aged 18 or older only."),
        ["addon.enable"] = ("Включить…", "Enable…"),
        ["addon.confirm.title"] = ("Контент для взрослых (18+)", "Adult content (18+)"),
        ["addon.confirm.text"] = ("Это дополнение добавляет в игру наготу и сексуальный контент. Оно не входит в основную сборку и ставится только по вашему желанию.\n\nНажимая «Мне есть 18, включить», вы подтверждаете, что:\n• вам исполнилось 18 лет;\n• просмотр такого контента разрешён законом там, где вы живёте;\n• вы включаете дополнение сами и для личного использования.",
                                  "This add-on adds nudity and sexual content to the game. It is not part of the main modlist and is installed only if you choose to.\n\nBy clicking “I am 18 or older — enable”, you confirm that:\n• you are 18 or older;\n• viewing this content is legal where you live;\n• you are enabling the add-on yourself, for personal use."),
        ["addon.nexus.step"] = ("Ещё один шаг на Nexus Mods. Регистрации недостаточно: моды для взрослых скачаются, только если вы сами включили их показ в своём аккаунте. На сайте Nexus Mods: значок профиля → Site preferences → Content blocking → включите «Show adult content». Включая эту настройку, вы подтверждаете Nexus Mods, что вам есть 18 лет.",
                                "One more step on Nexus Mods. Signing up is not enough: adult mods are downloaded only if you have enabled them in your own account. On the Nexus Mods site: profile icon → Site preferences → Content blocking → turn on “Show adult content”. By turning it on, you confirm to Nexus Mods that you are 18 or older."),
        ["addon.nexus.open"] = ("Открыть настройки Nexus", "Open Nexus settings"),
        ["addon.confirm.yes"] = ("Мне есть 18, включить", "I am 18 or older — enable"),
        ["addon.cancel"] = ("Отмена", "Cancel"),
        ["addon.level1"] = ("Контент для взрослых: нагота и откровенная одежда ({0})", "Adult content: nudity and revealing clothes ({0})"),
        ["addon.level2"] = ("Добавить откровенные сцены (сексуальные анимации). Только для взрослых.", "Also add explicit scenes (sexual animations). Adults only."),
        ["addon.mods"] = ("Что войдёт:", "What it adds:"),
        ["addon.mod.ok"] = ("установлен", "installed"),
        ["addon.mod.off"] = ("скачан, выключен", "downloaded, off"),
        ["addon.mod.new"] = ("будет скачан", "will be downloaded"),
        ["addon.install"] = ("Установить и включить", "Install and enable"),
        ["adult.off.saves"] = ("Выключить «18+»?\n\nСохранения, начатые с «18+», без него могут показать персонажа без головы или лица. На начатой игре лучше не выключать — или начни новую игру.\n\nВсё равно выключить?", "Turn off 18+?\n\nSaves started with 18+ may show the character without a head or face without it. Better not to turn it off on a started game — or start a new game.\n\nTurn it off anyway?"),
        ["addon.disable"] = ("Выключить дополнение", "Turn the add-on off"),
        ["addon.close"] = ("Закрыть", "Close"),
        ["addon.hint.premium"] = ("С Nexus Premium всё скачается само. С бесплатным аккаунтом откроется окно, где у каждого мода нужно нажать «Slow download».", "With Nexus Premium everything downloads by itself. With a free account a window opens where you click “Slow download” for each mod."),
        ["addon.downloading"] = ("Скачиваю {0} из {1}: {2}…", "Downloading {0} of {1}: {2}…"),
        ["addon.checking"] = ("Проверяю {0} из {1}: {2}…", "Checking {0} of {1}: {2}…"),
        ["addon.unpacking"] = ("Распаковываю {0} из {1}: {2}…", "Unpacking {0} of {1}: {2}…"),
        ["addon.enabling"] = ("Включаю моды в сборке…", "Switching the mods on in the modlist…"),
        ["addon.done"] = ("Готово: дополнение включено ({0} модов). Можно играть.", "Done: the add-on is on ({0} mods). You can play."),
        ["addon.disabled"] = ("Дополнение выключено. Файлы модов остались на диске — включить снова можно без скачивания.", "The add-on is off. Mod files stay on disk — you can turn it on again without downloading."),
        ["addon.notdownloaded"] = ("Не удалось скачать {0} модов для взрослых. Скорее всего, в вашем аккаунте Nexus Mods выключен показ контента для взрослых. Включите его: значок профиля → Site preferences → Content blocking → «Show adult content», затем нажмите «Установить и включить» ещё раз. Остальная сборка установлена и работает без этих модов.",
                                  "{0} adult mods could not be downloaded. Most likely adult content is turned off in your Nexus Mods account. Turn it on: profile icon → Site preferences → Content blocking → “Show adult content”, then click “Install and enable” again. The rest of the modlist is installed and works without these mods."),
        ["addon.errors"] = ("Не получилось:\n{0}", "Didn't work:\n{0}"),
        ["addon.err.mo2"] = ("Закройте Mod Organizer 2 и попробуйте снова: пока он открыт, он перезапишет список модов.", "Close Mod Organizer 2 and try again: while it is open it overwrites the mod list."),
        ["addon.err.hash"] = ("{0}: файл не совпал с контрольной суммой", "{0}: the file failed the checksum"),
        ["addon.err.unpack"] = ("{0}: не распаковался ({1})", "{0}: could not unpack ({1})"),
        ["addon.err.nomodlist"] = ("Не найден список модов сборки: {0}", "The modlist's mod list was not found: {0}"),
        ["addon.err.notinstalled"] = ("Сначала установите основную сборку.", "Install the main modlist first."),

        ["loaders.working"] = ("Готовим загрузчики модов в папке игры…", "Setting up the mod loaders in the game folder…"),
        ["loaders.nogame"] = ("Не нашли папку игры — загрузчики модов поставить некуда. Проверьте игру на странице установки сборки.", "Couldn't find the game folder, so the mod loaders can't be set up. Check the game on the modlist install page."),
        ["loaders.conflict"] = ("В папке игры уже есть свои файлы модов (например, от ручной установки):\n{1}\n\nОни отличаются от файлов сборки и могут ей мешать. Заменить их файлами сборки? Ваши файлы сохраним — кнопка «Вернуть чистую игру» вернёт их.\n\nПапка игры: {0}", "The game folder already has its own mod files (e.g. from a manual install):\n{1}\n\nThey differ from the modlist files and may get in the way. Replace them with the modlist files? Yours are kept — \"Restore clean game\" puts them back.\n\nGame folder: {0}"),
        ["loaders.missing"] = ("В папке сборки не нашли файлы:\n{0}\n\nБез них часть модов не запустится. Нажмите «Проверить файлы» на странице установки.", "These files are missing from the modlist folder:\n{0}\n\nWithout them some mods won't start. Press \"Verify files\" on the install page."),
        ["loaders.denied"] = ("Нет доступа к папке игры {0}. Запустите лаунчер от имени администратора.", "No access to the game folder {0}. Run the launcher as administrator."),
        ["loaders.error"] = ("Не получилось подготовить файлы в папке игры: {0}", "Couldn't set up the files in the game folder: {0}"),
        ["loaders.clean"] = ("Вернуть чистую игру", "Restore clean game"),
        ["foreign.text"] = ("В папке игры ({0}) лежат моды, которых нет в сборке:\n\n{1}\n\nОни загрузятся вместе со сборкой и часто вызывают вылеты. Если игра вылетает — перенеси их из папки игры в другое место. Лаунчер их не трогает.\n\nВсё равно играть?", "The game folder ({0}) has mods that are not part of the modlist:\n\n{1}\n\nThey load together with the modlist and often cause crashes. If the game crashes, move them out of the game folder. The launcher doesn't touch them.\n\nPlay anyway?"),
        ["loaders.clean.confirm"] = ("Убрать из папки игры загрузчики модов, которые поставил лаунчер, и то, что они создали (логи, настройки CET)? Ваши собственные файлы, если лаунчер их заменял, вернутся на место.\n\nСборка останется — при следующем «Играть» загрузчики поставятся снова.", "Remove the mod loaders the launcher put into the game folder and what they created (logs, CET settings)? Your own files, if the launcher replaced them, are put back.\n\nThe modlist stays — the next PLAY sets the loaders up again."),
        ["loaders.clean.done"] = ("Готово: в папке игры ничего не осталось от сборки. Сборка на месте — «Играть» поставит загрузчики снова.", "Done: nothing from the modlist is left in the game folder. The modlist is still there — PLAY sets the loaders up again."),
        ["loaders.clean.kept"] = ("Готово, но эти файлы оставили — их изменили после установки: {0}", "Done, but these files were kept because they changed after setup: {0}"),
        ["loaders.clean.running"] = ("Сначала закройте игру.", "Close the game first."),
        ["play.checking"] = ("Проверяем версию игры…", "Checking the game version…"),
        ["play.version.title"] = ("Игра обновилась", "The game was updated"),
        ["play.version.text"] = ("{0} сейчас версии {1}, а сборка {2} сделана для версии {3}.\n\nПосле обновления игры моды часто перестают работать, пока их авторы не выпустят исправления. Лучше дождаться новой версии сборки — она появится в лаунчере сама.\n\nСовет: выключите автообновление игры в Steam / Epic / GOG.\n\nВсё равно запустить?", "{0} is now version {1}, but {2} is made for version {3}.\n\nAfter a game update mods often stop working until their authors release fixes. It is better to wait for a new modlist version — it will appear in the launcher by itself.\n\nTip: turn off automatic game updates in Steam / Epic / GOG.\n\nLaunch anyway?"),
        ["play.watch"] = ("Игра запускается. Лаунчер следит за запуском — если что-то пойдёт не так, подскажет, что делать.", "The game is starting. The launcher is watching — if something goes wrong, it will tell you what to do."),

        ["problem.notstarted.title"] = ("Игра не запустилась", "The game did not start"),
        ["problem.notstarted.text"] = ("Mod Organizer открылся, но игра так и не стартовала за 3 минуты.", "Mod Organizer opened, but the game did not start within 3 minutes."),
        ["problem.early.title"] = ("Игра закрылась сразу после запуска", "The game closed right after starting"),
        ["problem.early.text"] = ("Игра проработала всего {0} с. Похоже, что-то мешает модам загрузиться.", "The game ran for only {0} s. Something seems to stop the mods from loading."),
        ["problem.crash.title"] = ("Игра вылетела", "The game crashed"),
        ["problem.crash.text"] = ("Игра закрылась с ошибкой через {0} мин. Если это случилось один раз — просто запустите снова.", "The game closed with an error after {0} min. If it happened once, just start it again."),
        ["problem.help"] = ("Что можно сделать:\n• Починить — лаунчер проверит файлы сборки и подскажет, как вернуть испорченные. Скачанные архивы уже есть, интернет почти не нужен.\n• Вернуться к прошлой версии — если недавно обновляли сборку.\n• Собрать отчёт и отправить его в поддержку (@FunkyLauncherBot в Telegram).", "What you can do:\n• Repair — the launcher checks the modlist files and helps restore damaged ones. The archives are already downloaded, so almost no internet is needed.\n• Go back to the previous version — if you recently updated the modlist.\n• Make a report and send it to support (@FunkyLauncherBot on Telegram)."),
        ["problem.crashfile"] = ("Отчёт о вылете: {0}", "Crash report: {0}"),
        ["problem.repair"] = ("ПОЧИНИТЬ", "REPAIR"),
        ["problem.rollback"] = ("Вернуться к версии {0}", "Back to version {0}"),
        ["problem.report"] = ("Собрать отчёт", "Make a report"),
        ["problem.close"] = ("Закрыть", "Close"),
        // 0.1.18: "Run as administrator" on the game exe → MO2 error 740 (support #142); texts by the Copywriter 21.11
        ["admin.flag.title"] = ("{0}: права администратора", "{0}: administrator rights"),
        ["admin.flag.hint"] = ("Из-за этой галочки Mod Organizer не запускает игру (ошибка 740). Нажми «Снять галочку» — уберём только её.", "This tick stops Mod Organizer from starting the game (error 740). Press “Remove the tick” — we remove only that."),
        ["admin.flag.text"] = ("У файла игры {0} стоит галочка «Запускать эту программу от имени администратора». Из-за неё Mod Organizer не может запустить игру: Windows отвечает ошибкой 740.\n\nСнять галочку? Уберём только её, больше ничего не изменится. Если Windows спросит разрешение, нажми «Да».", "The game file {0} has the “Run this program as an administrator” tick. Because of it Mod Organizer can't start the game: Windows answers with error 740.\n\nRemove the tick? We remove only that, nothing else changes. If Windows asks for permission, press “Yes”."),
        ["admin.flag.fix"] = ("Снять галочку", "Remove the tick"),
        ["admin.flag.done"] = ("Галочка снята. Можно играть.", "The tick is removed. You can play."),
        ["admin.flag.left"] = ("Галочку снять не получилось.", "Couldn't remove the tick."),
        ["admin.flag.uac"] = ("Windows не дала разрешение — галочка осталась.", "Windows didn't give permission — the tick is still there."),
        ["admin.flag.steps"] = ("Как снять вручную: открой папку {1}, нажми правой кнопкой на {0} → «Свойства» → «Совместимость» и сними галочку «Запускать эту программу от имени администратора». Если она серая, нажми «Изменить параметры для всех пользователей» и сними её там. Потом «ОК».", "To do it by hand: open the folder {1}, right-click {0} → Properties → Compatibility and untick “Run this program as an administrator”. If it is greyed out, press “Change settings for all users” and untick it there. Then OK."),
