        ["mod.sent"] = ("Уйдут название и ссылка, твой текст (и снимок, если приложил), название и версия сборки, версия (RU/EN), версия лаунчера и случайный номер установки. О ПК — ничего.", "Sent: the mod name and link, your text (and the screenshot, if you add one), the modlist name and version, its edition (RU/EN), the launcher version and a random installation ID. Nothing about your PC."),
        ["mod.consider"] = ("Мы рассмотрим предложение. Отвечать не будем; если мод войдёт в сборку — он появится в «Что нового».", "We'll consider your suggestion. We won't reply; if the mod makes it into the modlist, you'll see it in “What's new”."),
        ["mod.agree"] = ("Отправляя, ты соглашаешься, что мы обработаем эти данные (в том числе с помощью ИИ-сервиса), чтобы улучшить сборку. Ответа не будет. Не пиши в тексте личное. Подробнее — ", "By sending, you agree that we process this data (including with an AI service) to improve the modlist. We will not reply. Do not put personal data in the text. See "),
        ["mod.send"] = ("Предложить", "Suggest"),
        // 0.1.17: Wabbajack's window can't be opened without administrator rights (Copywriter 20.11)
        ["wj.admin.title"] = ("Не открылось окно входа в Nexus", "Nexus login window didn't open"),
        ["wj.admin.text"] = ("Windows даёт программам права администратора, а Wabbajack с ними не работает. Так бывает, если выключен контроль учётных записей или ты вошёл под встроенной учётной записью «Администратор». Включи контроль: Пуск → «Изменение параметров контроля учётных записей», ползунок выше самого низа, затем перезагрузи ПК. Или войди под обычной учётной записью.", "Windows gives programs administrator rights, and Wabbajack doesn't work with them. This happens when User Account Control is turned off or you're signed in to the built-in “Administrator” account. Turn UAC on: Start → “Change User Account Control settings”, move the slider above the bottom, then restart your PC. Or sign in with a regular account."),
        ["chat.title"] = ("Чат с поддержкой", "Chat with support"),
        ["chat.notice"] = ("Мы получим твой текст, файл (если приложишь), анонимный номер установки, название сборки и версию лаунчера — только чтобы ответить. Данные хранятся на нашем сервере в Германии: скриншоты 90 дней, сообщения и ответы 12 месяцев после последнего обращения. Не отправляй пароли и личные документы. Удалить данные можно в любой момент кнопкой ниже — сделаем за 10 рабочих дней. Подробнее — в политике конфиденциальности.", "We will receive your message, a file (if you attach one), an anonymous installation ID, the modlist name and the launcher version — only to reply to you. Data is stored on our server in Germany: screenshots for 90 days, messages and replies for 12 months after your last contact. Don't send passwords or personal documents. You can delete your data at any time with the button below — we will do it within 10 working days. More in the privacy policy."),
        ["chat.send"] = ("Отправить", "Send"),
        ["chat.attach"] = ("Приложить файл", "Attach file"),
        ["chat.attach.filter"] = ("Скриншот или отчёт|*.png;*.jpg;*.jpeg;*.zip|Все файлы|*.*", "Screenshot or report|*.png;*.jpg;*.jpeg;*.zip|All files|*.*"),
        ["chat.empty"] = ("Напиши вопрос, пожелание или что не работает — поддержка ответит здесь.", "Write a question, a wish or what doesn't work — support answers here."),
        ["chat.you"] = ("Ты", "You"),
        ["chat.support"] = ("Поддержка FunkyPlay", "FunkyPlay support"),
        ["chat.sending"] = ("Отправляю…", "Sending…"),
        ["chat.sent"] = ("Отправлено. Ответ появится здесь, окно можно закрыть.", "Sent. The answer will show up here; you can close the window."),
        ["chat.err.send"] = ("Не отправилось ({0}). Проверь интернет и попробуй ещё раз или напиши в Telegram.", "Not sent ({0}). Check the internet and try again, or write in Telegram."),
        ["chat.err.big"] = ("Файл больше 10 МБ — приложи поменьше.", "The file is over 10 MB — attach a smaller one."),
        // 0.1.18 (draft, for the Copywriter): an upload that broke three times; a report sent without a word about the problem
        ["chat.err.net"] = ("Не отправилось: связь оборвалась ({0}). Попробуй ещё раз. Если не выходит — отправь файл боту в Telegram.", "Not sent: the connection broke ({0}). Try again. If it keeps failing, send the file to the Telegram bot."),
        ["chat.err.what"] = ("Напиши в двух словах, что случилось: когда и что ты делал. Без этого по отчёту трудно найти причину.", "Write a few words about what happened: when and what you were doing. Without it the report is hard to read."),
        // 0.1.18 (draft): the server's limit (429) — the launcher waits and sends again by itself
        ["chat.wait"] = ("Сервер просит подождать. Отправлю сам через {0} с, окно не закрывай.", "The server asks to wait. I'll send it by myself in {0} s, keep the window open."),
        ["chat.err.busy"] = ("Сервер сейчас занят. Подожди {0} с и нажми «Отправить» ещё раз.", "The server is busy right now. Wait {0} s and press Send again."),
        // 0.1.18 (draft, for the Copywriter): the server asks to wait longer than a minute (Retry-After up to an hour)
        ["chat.err.later"] = ("Сервер просит подождать. Попробуй через {0} мин или напиши боту в Telegram.", "The server asks to wait. Try again in {0} min or message the Telegram bot."),
        ["chat.err.hour"] = ("Из этого лаунчера за час ушло много сообщений — сервер пока не принимает новые. Попробуй через час или напиши боту в Telegram.", "Many messages were sent from this launcher in the last hour — the server won't take more for now. Try in an hour or message the Telegram bot."),
        ["chat.err.files"] = ("За сутки уже отправлено 100 МБ файлов — это предел. Напиши текстом, а файл пришли завтра или боту в Telegram.", "100 MB of files were already sent today — that's the limit. Write it as text and send the file tomorrow or to the Telegram bot."),
        ["chat.telegram"] = ("Удобнее в Telegram? Написать боту @FunkyLauncherBot", "Prefer Telegram? Message @FunkyLauncherBot"),
        ["comp.voice.link"] = ("Страница авторов", "Authors' page"),
        ["comp.voice.link.hint"] = ("Ставится отдельно со страницы авторов, по их инструкции: включить её в сборку без их разрешения мы не можем.", "Installed separately from the authors' page, following their instructions: we can't include it in the modlist without their permission."),
        ["comp.voice"] = ("Русская озвучка", "Russian voice-over"),
        ["comp.voice.hint"] = ("Для русской версии: ~{0} ГБ, лаунчер скачает и поставит её сам.", "For the Russian version: ~{0} GB, the launcher downloads and installs it."),
        ["manual.hint.site"] = ("Нажми на странице кнопку «Скачать». Лаунчер сам поймает файл и поставит его в сборку.", "Press the Download button on the page. The launcher catches the file and installs it into the modlist."),
        ["comp.extra.working"] = ("Ставим дополнение…", "Installing the add-on…"),
