        ["check.tool.no"] = ("Не установлен {0}", "{0} is not installed"),
        ["check.tool.hint"] = ("Это бесплатное дополнение к игре, без него сборка может не запуститься. Поставь его там же, где у тебя игра, и нажми «Проверить ещё раз».", "This is a free add-on for the game; without it the modlist may not start. Install it where you got the game and press “Check again”."),
        ["play.tool.text"] = ("В папке игры нет {0} — без него {1} не запустится.\n\nВсё равно запустить?", "{0} is missing from the game folder — {1} won't start without it.\n\nStart anyway?"),
        ["check.dlc.hint"] = ("Дополнение обязательно для сборки.", "The expansion is required for this modlist."),
