        ["check.nexus.no"] = ("Нужен вход в Nexus", "Nexus login required"),
        ["check.nexus.hint"] = ("Нажмите «Войти в Nexus»: откроется Wabbajack → Settings → Nexus Mods → Log in. Лаунчер сам заметит вход.", "Click “Log in to Nexus”: Wabbajack opens → Settings → Nexus Mods → Log in. The launcher notices the login by itself."),
        ["check.modlist.ok"] = ("Файл сборки найден", "Modlist file found"),
