        ["web.fail.start.text"] = ("Windows не дала его запустить. Нажми «Повторить». Не помогло — открой страницу в обычном браузере.", "Windows didn't let it start. Press “Try again”. If that doesn't help, open the page in your normal browser."),
        ["web.fail.page.title"] = ("Страница не открылась", "The page didn't open"),
        ["web.fail.page.text"] = ("Нет связи с сайтом. Проверь интернет и нажми «Повторить» или открой страницу в обычном браузере.", "No connection to the site. Check your internet and press “Try again”, or open the page in your normal browser."),
