        ["web.fail.reason"] = ("Для поддержки: {0}", "For support: {0}"),
        ["web.fail.install"] = ("Установить WebView2", "Install WebView2"),
        ["web.fail.retry"] = ("Повторить", "Try again"),
        ["web.fail.outside"] = ("Открыть в обычном браузере", "Open in normal browser"),
        ["manual.outside.note"] = ("Если скачаешь мод в обычном браузере, лаунчер сам заберёт файл из папки «Загрузки».", "If you download the mod in your normal browser, the launcher picks up the file from your Downloads folder by itself."),
        ["manual.outside.status"] = ("Скачай файл в обычном браузере («Slow download»). Лаунчер ждёт его в папке «Загрузки» и сам откроет следующий мод.", "Download the file in your normal browser (“Slow download”). The launcher waits for it in your Downloads folder and opens the next mod by itself."),
        ["check.webview.ok"] = ("Встроенный браузер готов (WebView2 {0})", "Built-in browser ready (WebView2 {0})"),
